function reflectProcess(data,w,h,opts){
  opts=opts||{};
  var mode=opts.mode!=null?opts.mode:0;     // 0 水平, 1 垂直, 2 四向
  if(mode<0)mode=0; else if(mode>2)mode=2;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var sx=x, sy=y;
    if(mode===0||mode===2){ if(x*2>=w) sx=w-1-x; }
    if(mode===1||mode===2){ if(y*2>=h) sy=h-1-y; }
    var sp=(sy*w+sx)*4, dp=(y*w+x)*4;
    out[dp]=data[sp]; out[dp+1]=data[sp+1]; out[dp+2]=data[sp+2]; out[dp+3]=data[sp+3];
  }
  return out;
}

var EXPORTS={reflectProcess:reflectProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ReflectForgePure = EXPORTS; }
